import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { ContractService } from '@services/contract.service';
import { BlockchainConfigService } from '@services/blockchain-config.service';
import { IconComponent } from '@components/ui/icon/icon.component';
import { AddLockerModalComponent } from '@modals/add-locker-modal/add-locker-modal.component';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { ToastService } from '@services/toast.service';
import { ethers } from 'ethers';
import { LoggerService } from "@services/logger.service";

interface LockerInfo {
    address: string;
    name: string;
    network: string;
    chainId: number;
    isActive: boolean;
}

@Component({
    selector: 'app-locker-manager',
    standalone: true,
    imports: [CommonModule, RouterModule, IconComponent, AddLockerModalComponent, TranslateModule],
    templateUrl: './locker-manager.component.html',
    styleUrl: './locker-manager.component.css'
})
export class LockerManagerComponent implements OnInit, OnDestroy {
    lockers: LockerInfo[] = [];
    currentLocker: string | null = null;
    showModal = false;

    constructor(
        private contractService: ContractService,
        private blockchainConfigService: BlockchainConfigService,

        private translate: TranslateService,
        private toastService: ToastService, private logger: LoggerService
    ) { }

    ngOnInit() {
        this.logger.debug('[LockerManagerComponent] initialized');
        // Subscribe to current locker observable
        this.contractService.currentLocker$.subscribe(address => {
            this.currentLocker = address;
            if (this.lockers.length > 0) {
                this.lockers.forEach(l => l.isActive = l.address === address);
            }
        });

        // Load lockers when chainId is available
        this.contractService.chainId$.subscribe(chainId => {
            if (chainId) {
                this.lockers = []; // Clear existing lockers
                this.loadLockers(Number(chainId));
            }
        });
    }

    private loadLockers(currentChainId: number) {
        this.logger.debug('Loading lockers for chainId:', currentChainId);

        // Load config for current chain
        const config = this.blockchainConfigService.getChainConfig(currentChainId);

        this.logger.debug('Chain config:', config);

        if (config?.lockerContract?.address) {
            this.lockers.push({
                address: config.lockerContract.address,
                name: `${config.name} Locker`,
                network: config.name,
                chainId: config.chainId,
                isActive: config.lockerContract.address === this.currentLocker
            });
        }

        // Load custom lockers from localStorage
        const customLockers = localStorage.getItem('customLockers');
        if (customLockers) {
            const parsed = JSON.parse(customLockers);
            parsed.forEach((locker: any) => {
                if (locker.chainId && locker.chainId !== currentChainId) {
                    return; // Skip lockers from other chains
                }

                const normalizedAddress = ethers.getAddress(locker.address);
                const exists = this.lockers.some(l => ethers.getAddress(l.address) === normalizedAddress);

                if (!exists) {
                    this.lockers.push({
                        address: locker.address,
                        name: locker.name || 'Custom Locker',
                        network: locker.network || 'Custom',
                        chainId: locker.chainId || currentChainId,
                        isActive: locker.address === this.currentLocker
                    });
                }
            });
        }

        this.logger.debug('Loaded lockers:', this.lockers);
    }

    async selectLocker(address: string) {
        // Switch locker in ContractService securely
        await this.contractService.switchLocker(address);
        this.currentLocker = address;

        // Update isActive status
        this.lockers.forEach(l => l.isActive = l.address === address);

        // Reload to apply changes immediately
        window.location.href = '/dashboard';
    }

    openAddLockerModal() {
        this.showModal = true;
    }

    closeModal() {
        this.showModal = false;
    }

    onAddLocker(data: { address: string; name: string }) {
        // Prevent duplicate locker addresses
        const normalizedAddress = ethers.getAddress(data.address);
        const exists = this.lockers.some(l => ethers.getAddress(l.address) === normalizedAddress);

        if (exists) {
            this.toastService.error(`Locker at address ${data.address} is already in the list.`);
            return;
        }

        const currentChainId = Number(this.contractService.chainId$.value) || 0;

        const newLocker: LockerInfo = {
            address: data.address,
            name: data.name,
            network: 'Custom',
            chainId: currentChainId,
            isActive: false
        };

        this.lockers.push(newLocker);

        // Save to localStorage preserving other chains
        const customLockersStr = localStorage.getItem('customLockers');
        let customLockers: any[] = customLockersStr ? JSON.parse(customLockersStr) : [];

        // Remove existing entry for same address if any to avoid pure duplicate
        customLockers = customLockers.filter(l => ethers.getAddress(l.address) !== normalizedAddress);

        customLockers.push({
            address: data.address,
            name: data.name,
            network: 'Custom',
            chainId: currentChainId
        });

        localStorage.setItem('customLockers', JSON.stringify(customLockers));

        this.closeModal();
    }

    removeLocker(address: string) {
        if (address === this.currentLocker) {
            this.toastService.warning(this.translate.instant('LOCKER_MANAGER.WARNINGS.CANNOT_REMOVE_ACTIVE'));
            return;
        }

        if (confirm(this.translate.instant('LOCKER_MANAGER.CONFIRM_REMOVE'))) {
            this.lockers = this.lockers.filter(l => l.address !== address);

            // Update localStorage preserving other chains
            const customLockersStr = localStorage.getItem('customLockers');
            if (customLockersStr) {
                let customLockers: any[] = JSON.parse(customLockersStr);
                const normalizedAddress = ethers.getAddress(address);
                customLockers = customLockers.filter(l => ethers.getAddress(l.address) !== normalizedAddress);
                localStorage.setItem('customLockers', JSON.stringify(customLockers));
            }
        }
    }


    copyAddress(address: string) {
        navigator.clipboard.writeText(address).then(() => {
            this.toastService.success(this.translate.instant('LOCKER_MANAGER.SUCCESS.COPY'));
        }).catch(err => {
            this.logger.error('Failed to copy: ', err);
            this.toastService.error(this.translate.instant('LOCKER_MANAGER.ERRORS.COPY_FAILED'));
        });
    }

    ngOnDestroy(): void {
        this.logger.debug('[LockerManagerComponent] destroyed');
    }
}
